  deleteInherited: "\u042D\u0442\u043E\u0442 \u0441\u0435\u0440\u0432\u0435\u0440 \u043F\u0440\u0438\u0445\u043E\u0434\u0438\u0442 \u0438\u0437 \u043D\u0438\u0436\u043D\u0435\u0433\u043E \u0441\u043B\u043E\u044F \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438: \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C, \u043D\u043E \u043D\u0435 \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u0437\u0434\u0435\u0441\u044C.",
  watchError: "\u0416\u0438\u0432\u043E\u0435 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E: {error}",
